"""Section 2 (phone-only plan): wires the server price feed in. backend/feed.py and tests/test_feed.py are written just before this by the same command.
Adds two admin routes, the feed_on setting, the alerts import fix, the Price feed card in the admin panel, a README section and a HANDOFF line.
Each old text must appear exactly once or NOTHING is changed. Safe to run twice."""
import sys, os

APP_NEW = "@app.get('/api/admin/feed')\n@need(admin=True)\ndef admin_feed_get(u): return jsonify(feed.status())\n\n@app.post('/api/admin/feed')\n@need(admin=True)\ndef admin_feed_set(u):\n    j = _j()\n    if j.get('check'): return jsonify(feed.check())\n    if 'on' in j:\n        if not isinstance(j['on'], bool): return jsonify(error='on must be true or false'), 400\n        st.put('feed_on', '1' if j['on'] else '0')\n        if j['on']: threading.Thread(target=lambda: feed.tick(_scan), daemon=True).start()       # first round now, not in a minute\n    return jsonify(feed.status())\n\n"
CARD = '<h3 style="margin:8px 0 0">Price feed</h3><p class="note">Lets the server get gold prices by itself, so signals reach your phone with no PC. It uses Yahoo gold futures, usually a few dollars away from the FBS price, so check every level on your MT5 chart before you place a trade. Press Check first: it only tests the download.</p><div style="display:flex;gap:8px;flex-wrap:wrap"><button class="btn" id="pfChk">Check</button><button class="btn primary" id="pfOn">Turn on</button><button class="btn" id="pfOff">Turn off</button><button class="btn" id="pfRef">Status</button></div><p class="note" id="pfMsg" role="status"></p>'
JS = ' function pfShow(s){var t=[];t.push(s.on?"Feed is ON.":"Feed is OFF.");if(s.note)t.push(s.note);Object.keys(s.sym||{}).forEach(function(x){var v=s.sym[x];if(v&&v.last)t.push(x+" last candle "+new Date(v.last*1000).toISOString().slice(0,16).replace("T"," ")+" UTC, close "+v.close+".")});if(s.err)t.push("Problem: "+s.err);if(s.on&&!s.ok&&!s.err)t.push("First round is running, press Status in a minute.");$("#pfMsg").textContent=t.join(" ")}\n function pfCall(body,b){b.disabled=true;$("#pfMsg").textContent="Working...";return SXA.api("/api/admin/feed",{method:"POST",body:body}).catch(function(e){$("#pfMsg").textContent=e.message||"Not done";return null}).then(function(r){b.disabled=false;return r})}\n $("#pfChk").onclick=function(){pfCall({check:true},this).then(function(r){if(r)$("#pfMsg").textContent=(r.ok?"Download works. ":"Download failed. ")+r.msg})};\n $("#pfOn").onclick=function(){pfCall({on:true},this).then(function(r){if(r){pfShow(r);tst("Price feed turned on")}})};\n $("#pfOff").onclick=function(){pfCall({on:false},this).then(function(r){if(r){pfShow(r);tst("Price feed turned off")}})};\n $("#pfRef").onclick=function(){var b=this;b.disabled=true;SXA.api("/api/admin/feed").then(pfShow).catch(function(e){$("#pfMsg").textContent=e.message||"Not done"}).then(function(){b.disabled=false})};\n SXA.api("/api/admin/feed").then(pfShow).catch(function(){});\n'
README = '## Phone only (no PC): the server price feed\nIf you only have a phone, the server can get gold candles by itself, so phone mode has signals without an EA or the Windows app. Free, off by default.\n- **Switch on:** sign in as admin, open `#admin`, **Price feed** card: press **Check** (it only tests the download from your server), then **Turn on**, then start the bot on Home (with no EA this only means "look for signals"). Or set the Render variable `FEED_ON=1`.\n- **What you get:** about once a minute the server downloads closed 15-minute and 1-hour candles (Yahoo, `FEED_MAP`, default `XAUUSD:GC=F`), runs the same strategies and gates, and sends phone-mode people the signal with their lot size. **It never places a trade.** You place it by hand in the FBS / MT5 phone app.\n- **Honest limits:** Yahoo gold is the *futures* price, usually a few dollars from FBS spot, with small jumps when the contract rolls. Check entry, stop and target on your MT5 chart first. Yahoo is unofficial and may refuse a cloud server; the card shows the exact reason. It pauses by itself while your own EA is online (two price sources would mix). Render free sleeps: ping `/healthz` every 10 minutes (UptimeRobot) while you want signals. Not tested against live Yahoo from Render yet: use **Check** first.\n- **Prove it:** `python tests/test_feed.py` (Yahoo is faked there).\n\n'
HAND = '- Phone-only price feed (Nov 18 plan, section 2): backend/feed.py (Yahoo candles -> same candle store -> same scan; off by default; pauses when an EA is online) + GET/POST /api/admin/feed + Price feed card in the admin panel + store default feed_on + tests/test_feed.py. Next: section 3 (my MT5 price box + Cent/Standard account setting), section 4 (test_assist.py + demo run).\n\n'
PH = '<h3 style="margin:8px 0 0">Phone alerts</h3>'
EDITS = [
 ('backend/store.py', "'strategies_off': '', 'strategies_solo': ''", "'feed_on': os.getenv('FEED_ON', '0'), 'strategies_off': '', 'strategies_solo': ''", "'feed_on': os.getenv"),
 ('backend/app.py', 'adminpass as ap, strategy_info as si', 'adminpass as ap, strategy_info as si, feed, alerts', 'strategy_info as si, feed, alerts'),
 ('backend/app.py', "@app.post('/api/admin/testprice')", APP_NEW + "@app.post('/api/admin/testprice')", "def admin_feed_get("),
 ('backend/app.py', "try:\n    from . import live; alerts.start()", "try: feed.start(_scan)\nexcept Exception as e: print('[feed] not started', e)\ntry:\n    from . import live; alerts.start()", 'feed.start(_scan)'),
 ('static/index.html', PH, CARD + PH, 'id="pfChk"'),
 ('static/index.html', ' var SUBS=[];\n', JS + ' var SUBS=[];\n', 'function pfShow('),
 ('README.md', '## 1) Deploy (Termux)', README + '## 1) Deploy (Termux)', '## Phone only (no PC): the server price feed'),
 ('docs/HANDOFF.md', '## REMAINING (do in this order', HAND + '## REMAINING (do in this order', 'Phone-only price feed (Nov 18 plan'),
]
if not os.path.isdir('backend') or not os.path.isdir('static'): print('STOP: run this from the repo folder (spacexbot-mt5)'); sys.exit(1)
if not os.path.exists('backend/feed.py'): print('STOP: backend/feed.py is missing'); sys.exit(1)
new = {}
for path, old, rep, marker in EDITS:
    t = new.get(path) if path in new else open(path, encoding='utf-8', newline='').read()
    if marker in t: new[path] = t; continue
    if t.count(old) != 1: print('STOP: cannot find exactly once in', path, '->', old[:60]); sys.exit(1)
    new[path] = t.replace(old, rep)
for path, t in new.items(): open(path, 'w', encoding='utf-8', newline='').write(t)
print('patched OK')
